import torch


def gen_inputs(ctx, device):
    shape = ctx["input__shape"]
    dtype = ctx["input__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype.replace("torch.", ""))
    if dtype in (torch.float16, torch.float32, torch.bfloat16, torch.float64):
        inp = torch.randn(shape, dtype=dtype, device=device)
    elif dtype == torch.bool:
        inp = torch.randint(0, 2, shape, dtype=dtype, device=device)
    else:
        inp = torch.randint(-8, 9, shape, dtype=dtype, device=device)
    return {"input": inp}


def run(input, diagonal):
    input.tril_(diagonal)
    return input
